                       void *hostPtrToReadInto,
                       BNDataType requestedFormat) = 0;
    /** Actual framebuffer dimensions (may differ from resize when e.g. upscaling forces even dims). */
    virtual vec2i getNumPixels() const { return vec2i(-1, -1); }
